/* Token Radar v2 - Dark Mode Theme */
:root {
  --canvas: #0d1117;
  --surface: #161b22;
  --surface-elevated: #21262d;
  --ink: #e6edf3;
  --muted: #8b949e;
  --border: #30363d;
  --accent: #58a6ff;
  --accent-hover: #79c0ff;
  --positive: #3fb950;
  --negative: #f85149;
  --warning: #d29922;
  --radius-control: 8px;
  --radius-panel: 12px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
  --shadow-1: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-2: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-3: 0 8px 24px rgba(0, 0, 0, 0.5);
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 14px/1.55 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 28px; line-height: 1.2; font-weight: 600; }
h2 { font-size: 19px; line-height: 1.25; font-weight: 600; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 600; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--step-2) var(--step-4);
  background: var(--surface); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--step-4); top: var(--step-4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1440px; margin: 0 auto; padding: var(--step-5) var(--step-6) var(--step-7); }
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--step-5);
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); flex: none; box-shadow: 0 0 12px var(--accent); }
.brand-name { font-family: var(--font-num); font-size: 12px; letter-spacing: 0.05em; color: var(--muted); text-transform: uppercase; }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-3); justify-content: flex-end; color: var(--muted); font-size: 12px; }
.top-meta span { white-space: nowrap; }

.lede { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(300px, 0.6fr); gap: var(--step-6); padding: var(--step-6) 0 var(--step-5); }
.lede p { color: var(--muted); max-width: 65ch; margin-top: var(--step-2); line-height: 1.6; }
.facts { display: grid; gap: var(--step-2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--step-5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--step-3); }
.fact b { font-family: var(--font-num); font-size: 14px; font-weight: 500; color: var(--ink); }
.fact span { color: var(--muted); font-size: 12px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--step-3); padding: var(--step-4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--step-1); }
.field label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--step-3); border: 1px solid var(--border); border-radius: var(--radius-control);
  background: var(--surface-elevated); min-width: 180px; transition: border-color 0.15s, box-shadow 0.15s;
}
.field input:focus, .field select:focus { border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent); outline: none; }
.field input { min-width: 300px; width: 100%; }
.tabs { display: flex; gap: var(--step-1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-elevated); }
.tabs button { min-height: 32px; padding: 0 var(--step-3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); font-weight: 500; transition: all 0.15s; }
.tabs button:hover { color: var(--ink); background: var(--surface); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: var(--canvas); box-shadow: var(--shadow-1); }
.count { margin-left: auto; color: var(--muted); font-size: 12px; align-self: center; font-family: var(--font-num); }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; box-shadow: var(--shadow-1); }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { padding: var(--step-2) var(--step-3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
th { color: var(--muted); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; background: var(--surface-elevated); }
th button { display: inline-flex; align-items: center; gap: var(--step-1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--accent); }
tbody tr { cursor: pointer; transition: background 0.1s; }
tbody tr:hover { background: var(--surface-elevated); }
tbody tr[data-selected="true"] { background: color-mix(in srgb, var(--accent) 12%, var(--surface)); box-shadow: inset 3px 0 0 var(--accent); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 11px; }
.pos { color: var(--positive); }
.neg { color: var(--negative) }
.bar { width: 100px; height: 5px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--accent), var(--positive)); box-shadow: 0 0 8px var(--accent); }
.implied { display: flex; align-items: center; gap: var(--step-2); }
.status { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 11px; white-space: nowrap; }
.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--warning); box-shadow: 0 0 8px var(--warning); }
.status.live::before { background: var(--positive); box-shadow: 0 0 8px var(--positive); }

.model { margin-top: var(--step-4); padding: var(--step-5); display: grid; gap: var(--step-3); }
.formula { font-family: var(--font-num); font-size: 12px; line-height: 1.8; color: var(--muted); overflow-wrap: anywhere; background: var(--surface-elevated); padding: var(--step-3); border-radius: var(--radius-control); border: 1px solid var(--border); }
.empty { padding: var(--step-7) var(--step-5); text-align: center; display: grid; gap: var(--step-3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--step-4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-elevated); font-weight: 500; transition: all 0.15s; }
.button:hover { border-color: var(--accent); color: var(--accent); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--canvas); }
.button.primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); color: var(--canvas); }

.detail {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 92vw); z-index: 10;
  background: var(--surface); border-left: 1px solid var(--border); padding: var(--step-5);
  overflow-y: auto; transform: translateX(0); transition: transform 200ms cubic-bezier(0, 0, 0.2, 1);
  box-shadow: var(--shadow-3);
}
.detail[hidden] { display: none; }
.detail { margin: 0 0 0 auto; max-height: 100%; }
.detail::backdrop { background: rgba(0, 0, 0, 0.6); backdrop-filter: blur(4px); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--step-4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 36px; min-height: 36px; padding: 0 var(--step-2); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-elevated); transition: all 0.15s; }
.close:hover { border-color: var(--negative); color: var(--negative); }
.detail h2 { margin-top: var(--step-1); }
.detail .sub { margin-top: var(--step-1); }
.detail-section { margin-top: var(--step-5); padding-top: var(--step-4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--step-2); font-size: 14px; }
.equation { display: grid; gap: var(--step-2); font-family: var(--font-num); font-size: 12px; }
.equation div { display: flex; justify-content: space-between; gap: var(--step-3); padding: var(--step-2) 0; border-bottom: 1px solid var(--border); }
.equation div:last-child { border-bottom: none; }
.equation span { color: var(--muted); }
.equation b { color: var(--ink); }
.steps { margin: 0; padding-left: var(--step-5); display: grid; gap: var(--step-3); counter-reset: step; }
.steps li { padding-left: var(--step-2); position: relative; line-height: 1.6; }
.steps li::before { counter-increment: step; content: counter(step); position: absolute; left: -var(--step-5); top: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--accent); color: var(--canvas); font-size: 11px; font-weight: 600; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.steps b { display: block; font-weight: 500; margin-bottom: var(--step-1); }
.cost { color: var(--muted); font-size: 11px; font-family: var(--font-num); }

.risk-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 100px; font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; }
.risk-badge.high { background: color-mix(in srgb, var(--negative) 20%, transparent); color: var(--negative); border: 1px solid color-mix(in srgb, var(--negative) 40%, transparent); }
.risk-badge.medium { background: color-mix(in srgb, var(--warning) 20%, transparent); color: var(--warning); border: 1px solid color-mix(in srgb, var(--warning) 40%, transparent); }
.risk-badge.low { background: color-mix(in srgb, var(--positive) 20%, transparent); color: var(--positive); border: 1px solid color-mix(in srgb, var(--positive) 40%, transparent); }

.score-chip { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 100px; font-size: 11px; font-family: var(--font-num); font-weight: 500; }
.score-chip.high { background: color-mix(in srgb, var(--positive) 15%, transparent); color: var(--positive); }
.score-chip.medium { background: color-mix(in srgb, var(--accent) 15%, transparent); color: var(--accent); }
.score-chip.low { background: color-mix(in srgb, var(--muted) 15%, transparent); color: var(--muted); }

@media (max-width: 960px) {
  .shell { padding: var(--step-4); }
  .lede { grid-template-columns: 1fr; gap: var(--step-4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--step-4); }
  .field input { min-width: 0; width: 100%; }
  .detail { width: 100vw; max-width: 100vw; border-left: none; border-top: 1px solid var(--border); }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
